-- دليل الوجهات — 21 دولة (قائمة CRM الحصرية)
-- نفّذ بعد: destinations_guide.sql ثم destinations_guide_add_highlights.sql
-- التوليد: node scripts/generate-destinations-guide-seed.mjs

INSERT INTO public.destinations_guide (
  country_id,
  city_id,
  culture,
  guidelines,
  weather_seasons,
  professional_impression,
  highlights
)
VALUES
('japan', 'tokyo', 'طوكيو مدينةٌ لا تُضاهى في التوازن بين المستقبل والأناقة اليابانية الهادئة: أبراجٌ زجاجية، أحياءٌ ضيقةٌ دافئة، ومطاعمٌ تُقدّم الطهي كفنٍّ دقيق. روحُها الانضباط المبتسم — كل شيء يعمل بسلاسة دون فقدان الذوق.', 'المترو هو العمود الفقري للتنقّل؛ اشترِ بطاقة سويكا أو باسمو. احترم الهدوء في العربات. الحجوزات للمطاعم المميزة ضرورية مسبقاً. البطاقات البنكية منتشرة؛ نقداً للأسواق الصغيرة.', 'الربيع (آذار–أيار) والخريف (أيلول–تشرين الأول) الأنسب لطقسٍ معتدلٍ وزهور أو أوراق. الصيف حارٌ ورطب؛ الشتاء باردٌ وجافٌ مع أيامٍ صافية. تجنّب أسبوع الذهبي إن رغبتَ في تجنّب الزحام الشديد.', 'انقل لعميلك صورة «عاصمةٍ لا تُدهشك مرةً واحدة بل كل يوم»: طوكيو للمسافر الراقي هي إيقاعٌ حضريٌ فاخر مع مساحاتٍ للتأمل — اقترح له مزج شيبويا وهاراجوكو مع يومٍ هادئٍ في أسواكا أو معبدٍ تقليدي، ثم عشاءً أوماكاسي يُختتم الرحلة.', '• حيّ أسواكا ومعبد سينسوجي
• شيبويا وهاراجوكو
• حدائق شينجوكو غيوين
• أوماكاسي وتجارب السوشي الراقية
• أحياء غينزا وأوموتيساندو للتسوق'),
('japan', 'kyoto', 'كيوتو روحُ اليابان القديمة: معابد خشبية، حدائق زِن، جيون بأزقّتها الهادئة، وشعورٌ بأنّ الزمن يبطئ. هنا يُعاش الوابي-سابي — جمالُ البساطة والعمق.', 'التنقّل بالحافلات والمترو؛ دراجات للأحياء السكنية. في جيون، تجنّب مطاردة الجييشا للصور. احجز الريوكان مبكراً. بعض المعابد تتطلب حجوزات.', 'الربيع والخريف مثاليان (ساكورا وخريفٌ مشتعل). الصيف حار؛ الشتاء بارد لكنه صافٍ. تشرين الثاني مزدحمٌ لألوان الخريف.', 'قدّم كيوتو كـ«صمتٍ فاخرٍ يتحدّث»: للعميل الذي يبحث عن معنى لا عن ضجيج — ليالي في ريوكان، شايٌ مُتقن، ومشيٌ في أزقةٍ تاريخية. هذه الوجهة تُباع بالانطباع لا بعدد المعالم.', '• معبد كيوميزو وفوشيمي إناري
• غابة الخيزران في أراشيياما
• جيون وهاناميكوجي
• معابد زِن روكوانجي وغينكاكوجي
• تجربة كيمونو أو شايٍ تقليدي'),
('japan', 'osaka', 'أوساكا قلبُ الكانساي المرِح: طعامٌ شعبيٌ فاخر، ناسٌ مباشرون ودودون، وليلٌ حافلٌ بالحياة. تُعرف بـ«مطبخ الأمة» حيث يُستمتع بالأكل في الشارع كاحتفال.', 'متروٌ كثيفٌ وفعّال؛ فكر في بطاقة يومية. دوتونبوري مزدحم لكنه أساسي. احجز مطاعم الكتشكاتسو والأوكونومياكي المشهورة مسبقاً في أوقات الذروة.', 'مشابهٌ لطوكيو؛ الربيع والخريف الألطف. الصيف حار؛ الشتاء معتدلٌ نسبياً مقارنةً بشمال اليابان.', 'أوساكا للعميل الذي يحبّ «الفخامة الشعبية»: نكهاتٌ قوية، طاقةً عالية، ويومٌ في أوساكا كاستراحةٍ مرحة بين كيوتو الهادئة ونارا التاريخية — اربطها في مسارٍ متوازن.', '• دوتونبوري وشارع الغوايكو
• قلعة أوساكا
• أونيفرسال ستوديوز (للعائلات)
• كيوبوري وتجارب الكتشكاتسو
• يومٌ في نارا أو كوبي قريباً'),
('japan', 'okinawa', 'أرخبيل أوكيناوا — حيث يلتقي المحيط الهادئ بتراث مملكة ريوكيو: مياهٌ فيروزيةٌ شفافةٌ، شعابٌ مرجانيةٌ، ومنتجعاتٌ خاصةٌ صممت لاسترخاء النخبة بعيداً عن زحام المدن اليابانية الكبرى. روحُ «إيكيغاي» البحرية: إيقاعٌ بطيءٌ وفخامةٌ هادئة.', 'رحلاتٌ داخليةٌ من طوكيو/أوساكا إلى ناها أو جزيرةٌ أصغر؛ انتقالاتٌ بالسيارة أو اليخت الخاص في الجزر البعيدة. احترم الشعابَ والحياةَ البحرية؛ بعض الشواطئ تابعةٌ لفنادقٍ فاخرةٍ حصرياً. احجز الفيلات المائية والسبا مسبقاً في الموسم.', 'مناخٌ شبه مداريٌ لطيف؛ أبريل–يونيو وسبتمبر–نوفمبر مثاليان للبحر والغوص. الصيف حارٌ مع موسمٍ مطري؛ الشتاء دافئٌ نسبياً — مثاليٌ للهروب من البرد.', 'قدّم أوكيناوا كـ«اليابان التي لا تُروّج لنفسها بصخب»: للعميل الذي يبحث عن مياهٍ كاريبيةٍ بروحٍ يابانيةٍ راقية — اقترح إقامةً في منتجعٍ راقٍ على خليجٍ خاصٍ، غوصاً مع مرشدٍ، ويوماً لاستكشاف قلاع شوري وثقافةٍ أوكيناويةٍ أصيلة.', '• شواطئٌ ومنتجعاتٌ فاخرةٌ (مياهٌ فيروزية)
• جزيرةٌ إشيغاكي/مياكو للعزل والغوص
• موقعٌ شوري للتراث الملكي
• أكواريومٌ وشعابٌ مرجانية
• تجارب سباٍ ورفاهيةٍ على الشاطئ'),
('japan', 'hokkaido', 'هوكايدو — الجزيرة الشمالية البكر: ثلوجٌ ناعمةٌ تغطي الغابات والبراكين الخامدة، وينابيعٌ حارةٌ (أونسن) تفوح ببخارٍ يشفي الإرهاق. وجهةٌ للتزلج الفاخر والمأكولات البحرية الشمالية والهدوء الألبي الآسيوي.', 'قطارٌ سريعٌ من طوكيو أو رحلاتٌ داخليةٌ إلى سابورو/تشيتوزه. في الشتاء: معداتٌ دافئةٌ وحجوزاتٌ لممرات نيسيكو أو فورانو. الأونسن تتطلب آداباً (غسلٌ قبل الحمام). تأجيرٌ سياراتٌ مفيدٌ بين المدن والمنتجعات.', 'شتاءٌ طويلٌ ثلجيٌ — ذروةُ التزلج ديسمبر–مارس. صيفٌ معتدلٌ ومزهٍ مثاليٌ للمشي وحقول اللافندر (يوليو). الربيع والخريف ألوانٌ خلابةٌ مع ازدحامٍ أقل.', 'هوكايدو «ألبٌ يابانيٌ بذوقٍ Wanderloom»: للعميل الذي يريد شتاءً فاخراً أو صيفاً أخضرً هادئاً — اربط بين نيسيكو أو روسوتسو وتجربةٍ أونسنٍ في ريوكانٍ أو منتجعٍ فاخرٍ مع مأكولاتٍ بحريةٍ شمالية.', '• نيسيكو وتومامو للتزلج الفاخر
• أونسنٌ وريوكانٌ بإطلالاتٍ ثلجيةٍ أو غابية
• سابورو ومهرجان الثلج (موسم)
• فورانو وبيئيٌ لحقول الزهور
• بحيراتٌ بركانيةٌ وطبيعةٌ بكر'),
('korea', 'seoul', 'سيول مدينةٌ فوتوغرافيةٌ للمستقبل: أحياءٌ مفعمةٌ بالكي بوب والتصميم، فوق تاريخٍ ملكيٍ هادئ. ثقافةٌ تحترم الرتبة واللياقة مع طاقةٍ شبابيةٍ لا تهدأ.', 'متروٌ أنظف ودقيق؛ تطبيقات التاكسي (كاكاو) شائعة. البطاقات منتشرة. في المطاعم التقليدية، انتظر إشارة المضيف للبدء. احرص على الحجز للصالونات والمطاعم الراقية في جانغنام.', 'الربيع (أبريل–مايو) للزهور؛ الخريف (سبتمبر–أكتوبر) صافٍ ومريح. الصيف رطبٌ حار؛ الشتاء باردٌ وجاف. الضباب الدقيق أحياناً في الربيع.', 'صِفْ لعميلك سيول كـ«مستقبلٍ أنيقٍ يحترم جذوره»: تسوقٌ راقٍ في تشونغدام، تاريخٌ في القصور، وليلٌ في إيتايون — مناسبةٌ للمسافر الذي يريد التميّز دون المبالغة.', '• قصر غيونغبوك وقرية بوكان
• برج إن سيول ونهر تشونغتشون
• حيّ إيكسون دونغ للطعام
• جانغنام وشينسادونغ
• قرية بُكشون الهانوك'),
('korea', 'busan', 'بوسان وجهةٌ بحريةٌ انطباعية: جسورٌ، أسواقٌ للمأكولات البحرية، معابدٌ على البحر، وروحٌ أقلّ رسميةً من سيول مع نفس الانضباط الكوري.', 'القطار سريعٌ من سيول. التنقّل بالمترو والحافلات. سوق جاغالشي يستحقّ الصباح الباكر. الشواطئ مزدحمة في الصيف المحلي.', 'أكثر اعتدالاً من سيول؛ الصيف دافئٌ ورطب؛ الشتاء ألطف نسبياً. الخريف والربيع ممتازان للمشي على الكورنيش.', 'بوسان «أناقةٌ ساحليةٌ كورية»: للعميل الذي يفضّل البحر والمأكولات الطازجة — اقترح إقامةً فاخرةً مطلةً على الجسر، ويوماً في هيونداي أو تيغوك.', '• معبد هيدونغ يونغونغسا
• قرية غامتشون الثقافية
• شاطئ هايونداي وهوانغري
• سوق جاغالشي
• برج بوسان'),
('korea', 'jeju', 'جزيرة جيجو — بركانٌ نائمٌ يحتضن غاباتً أخضر، شلالاتٍ دراميةٌ، وساحلاً أسودٌ لافتاً. بعيداً عن إيقاع سيول، تمنح الجزيرة هدوءاً نادراً مع فنادقٍ مطلةٍ على المنحدرات والبحر، وثقافةً محليةً لطيفةً تُعرف بالتماسك العائلي والطبيعة المقدّسة.', 'تأجير سيارةٍ (رخصة دولية) الأنسب لاستكشاف الساحل والجبل في يومٍ واحد. الطقس يتقلب بين الساحل وهالاسان — طبقاتٌ وواقٍ. احجز منتجعاتٍ فاخرةٍ في الجنوب أو الغرب مسبقاً في الذروة المحلية. احترم مسارات الحمم والحدائق الوطنية.', 'الربيع (أزهارٌ) والخريف الأنسب لطقسٍ معتدلٍ ومشي. الصيف حارٌ ورطبٌ مع عطلاتٍ محليةٍ مزدحمة؛ الشتاء باردٌ رطبٌ لكنّه ساحرٌ للأونسن والمشاهد الضبابية.', 'جيجو «النسيمُ الذي يلي سيول»: للعميل الذي يريد طبيعةً بركانيةً ساحرةً وخصوصيةً — اقترح مساراً يجمع شلالات جيونغبانغ ومساراً في أُمبونغ، وإقامةً بإطلالةٍ على البحر، كختامٍ ملكيٍ بعد طاقةٍ حضريةٍ في سيول أو بوسان.', '• قمة هالاسان ومساراتٌ بركانية
• شلالات جيونغبانغ وتشونجييون
• ساحلٌ أسودٌ وجزيرةٌ أومودو
• غابة أُمبونغ وكهوفٌ من الحمم
• منتجعاتٌ فاخرةٌ في سيوجويبو وجونغمون'),
('china', 'beijing', 'بكين عاصمةٌ إمبراطوريةٌ بامتدادٍ معاصر: ساحاتٌ واسعة، جدرانٌ حمراء، وتقاليدٌ تتجلى في الفنون والمطبخ الشمالي الفخم. الوزنُ السياسي والتاريخي يمنحها هيبةً لا تُنسى.', 'المترو واسعٌ لكنّ المسافات كبيرة؛ خطط يومك بمناطق. الحجوزات للمعلم الكبير ضرورية. تطبيقات الدفع الصينية شائعة؛ نقدٌ وبطاقةٌ دولية في المناطق السياحية. احترم البروتوكول في المواقع التاريخية.', 'الربيع والخريف الأفضل (أبريل–مايو، سبتمبر–أكتوبر). الصيف حارٌ ورطب؛ الشتاء باردٌ وجافٌ مع رياح. الضباب الدخاني أحياناً في الشتاء.', 'بكين للعميل الذي يبحث عن «شرقٍ ملوكي»: ساحةٌ تيانانمن، المدينة المحرّمة، وتجربةٌ بكينيةٌ أصيلةٍ في بيوتٍ هوى تاريخيةٍ — قدّمها كبوابةٍ لفهم الصين العميقة لا السطحية.', '• المدينة المحرّمة وساحة تيانانمن
• سور الصين (بادالينغ/موتيانيو)
• قصر الصيف
• معبد السماء
• أحياء الهوتونغ الفاخرة'),
('china', 'shanghai', 'شانغهاي مدينةٌ أوروبيةٌ آسيويةٌ في آنٍ: الواجهة البحرية، أبراجٌ فائقة، وحيٌ فرنسيٌ أنيق. روحُها التجارةُ والأناقةُ والسرعة.', 'متروٌ ممتاز؛ تطبيقات التوصيل والتاكسي سهلة. الحجوزات للعروض والمطاعم الراقية. تجنّب الذروة في العطلات الذهبية الصينية إن أمكن.', 'الربيع والخريف مريحان. الصيف حارٌ ورطبٌ جداً؛ الشتاء باردٌ رطب. يونيو أمطارٌ موسمية.', 'شانغهاي «فخامةٌ شرقيةٌ عالمية»: للمسافر الذي يحبّ التصميم والمطبخ الفيوجن والفنادق الأيقونية — اقترح ليلةً على الواجهة البحرية وعشاءً في برجٍ مطلٍ.', '• الواجهة البحرية (البوند) وبُودونغ
• حيّ شينتياندي الفرنسي
• حديقة يُوي
• أسواقٌ فنيةٌ ومعارضٌ معاصرة
• تجارب مطبخٍ شانغهاي الحديث'),
('china', 'guangzhou', 'كوانزو عاصمةٌ تجاريةٌ عريقةٌ في كانتون: مطبخٌ كانتونيٌ رفيعٌ، تاريخٌ بحريٌ، ومزيجٌ حديثٌ بين الأبراج والأسواق التقليدية.', 'متروٌ جيد؛ المسافات بين الأحياء كبيرة. المطبخ الكانتوني يُقدّم على مائدةٍ مشتركة — جرّب الدايم سوم. البطاقات في الفنادق؛ تطبيقات محلية للحياة اليومية.', 'شبه مداريٌ رطب؛ الشتاء لطيفٌ نسبياً؛ الصيف طويلٌ وحارٌ. أفضل الفترات: تشرين الثاني–آذار تقريباً.', 'كوانزو «بوابةٌ جنوبيةٌ للذواقة»: للعميل الذي يضع الطعام في قلب الرحلة — اربطها بهونغ كونغ أو ماكاو في مسارٍ متعددٍ للوجهات.', '• برج كانتون ومنظرٌ حضريٌ
• معبدٌ لينغنان وأحياءٌ تقليدية
• تجارب ديم سوم فاخرة
• جزيرة شاميان الاستعمارية
• أسواقٌ ليليةٌ وحرفٌ يدوية'),
('canada', 'toronto', 'تورونتو مدينةٌ عالميةٌ متعددةٌ الثقافات على ضفاف أونتاريو: فنٌ، مطابخٌ لا تُحصى، وروحٌ ليبراليةٌ ودودة. الأبراج الزجاجية تلتقي بأحياءٍ تاريخيةٍ هادئة.', 'متروٌ وترامٌ؛ تيب كارد مفيد. إكرامياتٌ ~15–18٪ في المطاعم. الشتاء باردٌ — طبقاتٌ دافئة. الحجوزات للمطاعم الراقية في وسط المدينة.', 'الصيف دافئٌ ومشمسٌ (أفضلٌ للسياحة). الخريف ألوانٌ جميلة. الشتاء باردٌ مع ثلج؛ الربيع متأخرٌ نسبياً.', 'تورونتو «أناقةٌ كنديةٌ بلا تكلف»: للعميل الذي يفضّل مدناً آمنةً ونظيفةً مع مشهدٍ طعامٍ عالميٍ — اقترح برج سي إن ويوماً في جزر تورنتو أو نياغارا كامتداد.', '• برج CN ومنطقة وسط المدينة
• سوق سانت لورانس وكينغستون ماركت
• متحف روم الملكي
• جزيرة تورنتو
• رحلةٌ يوميةٌ لشلالات نياغارا'),
('canada', 'vancouver', 'فانكوفر مدينةٌ بين الجبال والبحر: طبيعةٌ خلابةٌ على بعدٍ دقائق من وسطٍ عصريٍ. روحٌ باسيفيكيةٌ راقيةٌ واهتمامٌ بالاستدامة والصحة.', 'سيارةٌ أو متروٌ وسكاي ترين. المطر شائعٌ في الشتاء — احضر طبقاتٍ. الحجوزات لجسر كابيلانو أو جبل غروس في الموسم. إكرامياتٌ كالعادة في أمريكا الشمالية.', 'شتاءٌ معتدلٌ رطب؛ صيفٌ مشمسٌ نادراً ما يكون حاراً جداً. الربيع والصيف مثاليان للطبيعة.', 'فانكوفر «فخامةٌ طبيعيةٌ»: للمسافر النشيط الذي يريد التزلج في ويسلر أو الإبحار والمشي في يومٍ واحد — قدّمها كوجهةٍ صحيةٍ أنيقة.', '• حديقة ستانلي وواجهة كندا مكان
• جسر كابيلانو المعلق
• غاستاون التاريخي
• جزيرة غرانفيل
• يومٌ في ويسلر'),
('canada', 'montreal', 'مونتريال مدينةٌ فرنكوفونيةٌ أمريكيةٌ: كاتدرائياتٌ، مهرجاناتٌ، مطبخٌ فرنسيٌ مبتكر، وليلٌ حيٌّ. ثقافةٌ فنيةٌ وموسيقيةٌ عميقة.', 'فرنسيةٌ في الشارع؛ الإنجليزية منتشرة. متروٌ بسيط. الشتاء قاسٍ — مهرجان الثلج يستحقّ التجربة. إكرامياتٌ في المطاعم.', 'الصيف دافئٌ ومفعمٌ بالمهرجانات. الخريف جميل. الشتاء باردٌ جداً؛ الربيع متقلب.', 'مونتريال «باريسٌ أمريكيةٌ بروحٍ خاصة»: للعميل الذي يحبّ الفن والمطبخ والحياة الليلية — اربطها بكيبيك القديمة في امتدادٍ رومانسي.', '• مونت رويال وإطلالاتٌ على المدينة
